import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.BvlN9b-o.js";const k=JSON.parse('{"title":"验证可选桌面客户端的资源趋势","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/desktop-soak","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"tutorials/desktop-soak.md","filePath":"tutorials/desktop-soak.md"}'),o={name:"tutorials/desktop-soak.md"};function d(r,e,p,l,n,h){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="验证可选桌面客户端的资源趋势" tabindex="-1">验证可选桌面客户端的资源趋势 <a class="header-anchor" href="#验证可选桌面客户端的资源趋势" aria-label="Permalink to &quot;验证可选桌面客户端的资源趋势&quot;">​</a></h1><p>只有提供 Electron 客户端时才需要 Desktop Soak。后端文档、HTTP 合同和静态文档站点不依赖它。本指南观察真实桌面壳反复使用共享页面时的 RSS、JS 堆、DOM 节点和监听器；增长观察是报告材料，单次长测不能判定泄漏。</p><p>前提是<a href="./electron-shell">桌面壳</a>已能加载自己的 Web 页面、后端业务合同已验证，机器有 Docker、pnpm 和显示环境或 xvfb。命令在仓库根目录运行。</p><h2 id="先验证采集链路" tabindex="-1">先验证采集链路 <a class="header-anchor" href="#先验证采集链路" aria-label="Permalink to &quot;先验证采集链路&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DESKTOP_SOAK_DURATION_SECS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">25</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> perf-desktop-soak</span></span></code></pre></div><p>当前<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/scripts/perf/desktop-soak.mjs" target="_blank" rel="noreferrer">运行器</a>创建隔离 PostgreSQL/Redis/RustFS/Mailpit、API/Web 与测试用户目录，通过公开 HTTP 播种知识库数据，再打开真实 Electron。结束删除自己的容器、卷和用户目录；不使用开发数据。</p><p>成功生成 <code>.scratch/perf/desktop-soak-report.json</code>，包括原始时间序列、聚合、增长观察、git SHA、desktop/Electron 版本和采样配置。短运行只证明接线和采集，不代表长期资源稳定。</p><h2 id="把循环改为自己的页面" tabindex="-1">把循环改为自己的页面 <a class="header-anchor" href="#把循环改为自己的页面" aria-label="Permalink to &quot;把循环改为自己的页面&quot;">​</a></h2><p>当前<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/tests/desktop/soak.spec.ts" target="_blank" rel="noreferrer">采集场景</a>执行“列表 → 详情 → 附件刷新/下载/上传 → 删除本轮附件 → 打开并取消弹窗 → 采样 → 返回列表”。迁移到自己的业务时：</p><ol><li>用自己的公开 API 播种固定规模数据，通过真实页面登录和导航。</li><li>选择最重且可重复的一屏作为采样点，例如详情、文件与任务面板均已加载之后。</li><li>清理本轮新增数据，让每轮看到相同规模；否则资源增长可能来自数据集增长。</li><li>保留真实下载、网络请求和组件生命周期，只改页面选择器与业务操作。</li><li>在业务所有权清单登记场景/采集文件，避免移除业务后留下无效入口。</li></ol><h2 id="指标的边界" tabindex="-1">指标的边界 <a class="header-anchor" href="#指标的边界" aria-label="Permalink to &quot;指标的边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>来源</th><th>限制</th></tr></thead><tbody><tr><td><code>rendererRssKiB</code></td><td>主进程 <code>app.getAppMetrics()</code> 的渲染进程 working set</td><td>包含 Chromium/分配器行为，增长不等于 JS 泄漏</td></tr><tr><td><code>heapKiB</code></td><td><code>performance.memory.usedJSHeapSize</code></td><td>GC 引起波动，缺失时记录 null</td></tr><tr><td><code>domNodes</code></td><td>当前文档元素数量</td><td>必须在可比的页面状态采样</td></tr><tr><td><code>listeners</code></td><td>包裹 EventTarget 的净注册数</td><td>只统计 window/document/body/根容器等长命目标，不是全部监听器清册</td></tr></tbody></table><p>监听器计数按目标、事件类型、捕获阶段和 listener 去重，处理 <code>once</code> 与 AbortSignal 的移除。初始化脚本只用于测量，不改变生产业务实现。</p><h2 id="长跑、复跑与失败处理" tabindex="-1">长跑、复跑与失败处理 <a class="header-anchor" href="#长跑、复跑与失败处理" aria-label="Permalink to &quot;长跑、复跑与失败处理&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DESKTOP_SOAK_DURATION_SECS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">3600</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> perf-desktop-soak</span></span></code></pre></div><p>默认循环 300 秒，预热 <code>DESKTOP_SOAK_WARMUP_SECS=15</code>，采样 <code>DESKTOP_SOAK_SAMPLE_MS=2000</code>。<code>PERF_SCALE</code> 控制当前参考数据规模。预热让初始加载与懒加载先完成，避免把冷启动与稳态混为同一序列。</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/scripts/perf/desktop-report.mjs" target="_blank" rel="noreferrer">报告整形</a>比较首末四分位中位数，增长超过 25% 时记录 <code>growthNotes</code>，不改变退出码。重复同一版本与规模，区分轮内分配、GC 与跨轮积累；保留原始点和运行环境。页面断言或启动失败仍会让命令失败，应先修复真实失败，再解释曲线。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/tooling/desktop-soak-report.test.mjs</span></span></code></pre></div><p>这个确定性报告测试进入日常门禁。真实 GUI 冒烟与长测用于客户端里程碑和夜跑，长测不属于普通 PR 的 <code>just check</code>。知识库移除时当前场景与运行器随示例删除，原配方会指向已删除的脚本；通用报告整形保留。自己的业务需要重建运行器与采集场景，并更新配方后再运行长测。</p><p>下一步：<a href="./add-example">把自己的页面贡献给应用壳</a>。</p><hr><p>源码版本：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/tutorials/26-desktop-soak.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>',22)])])}const b=t(o,[["render",d]]);export{k as __pageData,b as default};
